#include "stdlib/math/base/special/round10f.h"
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <sys/time.h>

#define NAME "round10f"
#define ITERATIONS 1000000
#define REPEATS 3

static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec / 1.0e6;
}

static float rand_float( void ) {
	return (float)rand() / ( (float)RAND_MAX + 1.0f );
}

static double benchmark( void ) {
	float x[100];
	volatile float y; /* prevent compiler optimization */
	double elapsed;
	double t;
	int i;

	for ( i = 0; i < 100; i++ ) {
		x[ i ] = ( 1.0e4f * rand_float() ) - 5.0e3f;
	}

	t = tic();
	for ( i = 0; i < ITERATIONS; i++ ) {
		y = stdlib_base_round10f( x[ i % 100 ] );
	}
	elapsed = tic() - t;

	if ( y != y ) {
		printf( "should not return NaN\n" );
	}

	return elapsed;
}

int main( void ) {
	double elapsed;
	int i;

	srand( time( NULL ) );

	printf( "native::%s\n", NAME );
	for ( i = 0; i < REPEATS; i++ ) {
		elapsed = benchmark();
		printf( "  elapsed: %0.9f sec\n", elapsed );
	}
}
